// Дополнения к урокам (engine.js, docs/site.md «Учебник английского»): NOTE(id урока, {...}).
// crow — реплика вороны Невермор в начале урока; mk — «Своими словами»: «задание|нужное слово/вариант;…|пример # пояснение»;
// etym — [[слово, история]] «Откуда слово»; книга «Алиса» (часть урока — book.js): ru — о чём отрывок, gl — подсказки слов,
// tf / ch — задания (как в чтении), bmk — написать своё по отрывку, etb — история слова или отсылки из Кэрролла.
window.EN_NOTES = {};
function NOTE(id, o) { window.EN_NOTES[id] = o; }

